const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function drawingLink(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?`<a class="drawing-link" href="${escape(url.href)}" target="_blank" rel="noopener noreferrer">Open CAD ↗</a>`:'';}catch{return '';}}
export function partsRegister(parts){
 return `<div class="register-intro"><strong>DESIGN & FABRICATION DETAILS</strong><span>Plan the part here. Run the job on the production board.</span></div><div class="table-wrap"><table class="register-table"><thead><tr><th>Part / number</th><th>Material</th><th>Process</th><th>Qty</th><th>Subsystem</th><th>Drawing / source</th><th>Planning</th></tr></thead><tbody>${parts.map(p=>`<tr><td><button class="part-name" data-edit="${escape(p.id)}">${escape(p.name)}</button><div class="part-number">${escape(p.number||'No part number')}</div>${p.blocked?'<span class="blocked-tag">⚑ Blocked</span>':''}</td><td class="register-material">${p.material?escape(p.material):'<span class="missing-detail">Set material</span>'}</td><td>${p.process?escape(p.process):'<span class="missing-detail">Set process</span>'}</td><td><strong>${p.quantity}</strong></td><td>${escape(p.subsystem||'Unspecified')}</td><td>${drawingLink(p.cad)||'<span class="missing-detail">No drawing</span>'}<div class="source-label">${p.onshape?'ONSHAPE':'MANUAL RECORD'}</div></td><td><span class="planning-priority">${escape(p.priority)} priority</span><div class="part-number">${p.due?'Due '+escape(p.due):'No deadline'}</div></td></tr>`).join('')}</tbody></table></div>`;
}
